sql_queries:
SELECT deposit_type, ROUND(100.0 * AVG(is_canceled), 1) AS cancellation_rate
FROM bookings
GROUP BY deposit_type;

SELECT ROUND(100.0 * AVG(is_canceled), 1) AS cancellation_rate
FROM bookings
WHERE lead_time > 180;

SELECT ROUND(SUM(adr * total_nights)) AS lost_revenue
FROM bookings
WHERE is_canceled = 1 AND arrival_date_year = 2016;

SELECT customer_type, ROUND(100.0 * AVG(is_canceled), 1) AS cancellation_rate
FROM bookings
GROUP BY customer_type;

SELECT COUNT(*) AS canceled_bookings_with_previous_cancellation
FROM bookings
WHERE is_canceled = 1 AND previous_cancellations >= 1;
